// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

import "@openzeppelin/contracts/access/Ownable.sol";

/**
 * @title DNSResolver - Decentralized DNS resolution with connection pooling
 * @notice Resolves domain names to addresses with caching and pool management
 */
contract DNSResolver is Ownable {
    struct DNSRecord {
        address resolver;
        uint256 ttl;
        uint256 timestamp;
        bool exists;
    }

    struct ConnectionPool {
        address[] activeConnections;
        mapping(address => bool) isPooled;
        uint256 maxSize;
        uint256 currentIndex;
    }

    struct Zone {
        bytes32 zoneHash;
        mapping(bytes32 => DNSRecord) records;
        bytes32[] recordKeys;
        bool isPrivate;
        address zoneAdmin;
    }

    mapping(bytes32 => Zone) private zones;
    mapping(address => ConnectionPool) private pools;
    bytes32[] private zoneList;

    uint256 private constant MAX_POOL_SIZE = 50;
    uint256 private constant DEFAULT_TTL = 3600;

    event RecordUpdated(bytes32 indexed zoneHash, bytes32 indexed recordHash, address resolver);
    event ZoneCreated(bytes32 indexed zoneHash, address admin);
    event ConnectionPooled(address indexed poolOwner, address connection);

    modifier onlyZoneAdmin(bytes32 _zoneHash) {
        require(
            zones[_zoneHash].zoneAdmin == msg.sender || owner() == msg.sender,
            "Not zone admin"
        );
        _;
    }

    constructor() Ownable() {
        pools[msg.sender].maxSize = MAX_POOL_SIZE;
    }

    function createZone(string calldata _zoneName, bool _isPrivate) external returns (bytes32) {
        bytes32 zoneHash = keccak256(abi.encodePacked(_zoneName, msg.sender));
        require(zones[zoneHash].zoneAdmin == address(0), "Zone exists");

        zones[zoneHash].zoneHash = zoneHash;
        zones[zoneHash].isPrivate = _isPrivate;
        zones[zoneHash].zoneAdmin = msg.sender;
        zoneList.push(zoneHash);

        emit ZoneCreated(zoneHash, msg.sender);
        return zoneHash;
    }

    function setRecord(
        bytes32 _zoneHash,
        string calldata _name,
        address _resolver,
        uint256 _ttl
    ) external onlyZoneAdmin(_zoneHash) {
        bytes32 recordHash = keccak256(abi.encodePacked(_name));
        Zone storage zone = zones[_zoneHash];

        if (!zone.records[recordHash].exists) {
            zone.recordKeys.push(recordHash);
        }

        zone.records[recordHash] = DNSRecord({
            resolver: _resolver,
            ttl: _ttl > 0 ? _ttl : DEFAULT_TTL,
            timestamp: block.timestamp,
            exists: true
        });

        emit RecordUpdated(_zoneHash, recordHash, _resolver);
    }

    function resolve(bytes32 _zoneHash, string calldata _name) external view returns (address, uint256) {
        bytes32 recordHash = keccak256(abi.encodePacked(_name));
        DNSRecord storage record = zones[_zoneHash].records[recordHash];

        require(record.exists, "Record not found");
        require(block.timestamp - record.timestamp <= record.ttl, "Record expired");

        return (record.resolver, record.ttl);
    }

    function addToPool(address _connection) external {
        ConnectionPool storage pool = pools[msg.sender];
        if (pool.maxSize == 0) pool.maxSize = MAX_POOL_SIZE;

        require(pool.activeConnections.length < pool.maxSize, "Pool full");
        require(!pool.isPooled[_connection], "Already pooled");

        pool.activeConnections.push(_connection);
        pool.isPooled[_connection] = true;

        emit ConnectionPooled(msg.sender, _connection);
    }

    function getPoolStatus(address _owner) external view returns (uint256 active, uint256 max) {
        return (pools[_owner].activeConnections.length, pools[_owner].maxSize);
    }

    /**
     * @notice Enumerate zone records for diagnostics
     * @dev Access control enforced for all zones
     */
    function enumerateZoneRecords(bytes32 _zoneHash) 
        external 
        view 
        returns (bytes32[] memory keys, address[] memory resolvers) 
    {
        Zone storage zone = zones[_zoneHash];

        // Access check: all zones restricted to admin or owner
        require(
            msg.sender == zone.zoneAdmin || msg.sender == owner(),
            "Not authorized"
        );

        uint256 len = zone.recordKeys.length;
        keys = new bytes32[](len);
        resolvers = new address[](len);

        for (uint256 i = 0; i < len; i++) {
            keys[i] = zone.recordKeys[i];
            resolvers[i] = zone.records[zone.recordKeys[i]].resolver;
        }

        return (keys, resolvers);
    }

    /**
     * @notice List zones owned by the caller
     * @dev Only returns zones where caller is admin, plus public zone metadata for owner
     */
    function listZones(uint256 _offset, uint256 _limit) 
        external 
        view 
        returns (bytes32[] memory hashes, bool[] memory privacyFlags) 
    {
        // First pass: count eligible zones
        uint256 count = 0;
        uint256 end = _offset + _limit;
        if (end > zoneList.length) end = zoneList.length;

        for (uint256 i = _offset; i < end; i++) {
            bytes32 zh = zoneList[i];
            if (zones[zh].zoneAdmin == msg.sender || msg.sender == owner()) {
                count++;
            } else if (!zones[zh].isPrivate) {
                count++;
            }
        }

        hashes = new bytes32[](count);
        privacyFlags = new bool[](count);

        uint256 idx = 0;
        for (uint256 i = _offset; i < end; i++) {
            bytes32 zh = zoneList[i];
            if (zones[zh].zoneAdmin == msg.sender || msg.sender == owner()) {
                hashes[idx] = zh;
                privacyFlags[idx] = zones[zh].isPrivate;
                idx++;
            } else if (!zones[zh].isPrivate) {
                hashes[idx] = zh;
                privacyFlags[idx] = false;
                idx++;
            }
        }

        return (hashes, privacyFlags);
    }

    function getZoneRecordCount(bytes32 _zoneHash) external view returns (uint256) {
        Zone storage zone = zones[_zoneHash];
        require(
            msg.sender == zone.zoneAdmin || msg.sender == owner() || !zone.isPrivate,
            "Not authorized"
        );
        return zone.recordKeys.length;
    }

    function removeFromPool(address _connection) external {
        ConnectionPool storage pool = pools[msg.sender];
        require(pool.isPooled[_connection], "Not in pool");

        pool.isPooled[_connection] = false;

        // Swap and pop
        uint256 len = pool.activeConnections.length;
        for (uint256 i = 0; i < len; i++) {
            if (pool.activeConnections[i] == _connection) {
                pool.activeConnections[i] = pool.activeConnections[len - 1];
                pool.activeConnections.pop();
                break;
            }
        }
    }

    function rotatePoolConnection(address _poolOwner) external view returns (address) {
        ConnectionPool storage pool = pools[_poolOwner];
        require(pool.activeConnections.length > 0, "Empty pool");

        uint256 idx = uint256(keccak256(abi.encodePacked(block.timestamp, msg.sender))) % pool.activeConnections.length;
        return pool.activeConnections[idx];
    }
}
